WITH flattened_attrs AS (SELECT id, effective_from, tier_prices, discounts, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers WHERE effective_from BETWEEN '2024-01-19' AND '2025-05-22') SELECT CASE WHEN lowest_price >= 26 THEN 'PREMIUM' ELSE 'STANDARD' END AS lowest_price_tier, CASE WHEN avg_tier_price >= 34 THEN 'PREMIUM' ELSE 'STANDARD' END AS avg_tier_price_tier, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(entry_price), 2) AS avg_entry_price, MIN(lowest_price) AS min_lowest_price FROM flattened_attrs GROUP BY CASE WHEN lowest_price >= 26 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN avg_tier_price >= 34 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY avg_tier_price_tier;
